#include "bimob/canonical_json.hpp"
#include "bimob/engine.hpp"
#include <cctype>
#include <cmath>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <variant>
using namespace bimob;
namespace fs=std::filesystem;
namespace {
struct V{using A=std::vector<V>;using O=std::map<std::string,V>;std::variant<std::nullptr_t,bool,double,std::string,A,O>v=nullptr;};
class Parser{std::string s;size_t i=0;void ws(){while(i<s.size()&&std::isspace((unsigned char)s[i]))++i;}char take(){if(i>=s.size())throw std::runtime_error("Unexpected end JSON");return s[i++];}std::string str(){if(take()!='"')throw std::runtime_error("Expected quote");std::string r;while(i<s.size()){char c=take();if(c=='"')return r;if(c=='\\'){char e=take();switch(e){case '"':r+='"';break;case '\\':r+='\\';break;case '/':r+='/';break;case 'b':r+='\b';break;case 'f':r+='\f';break;case 'n':r+='\n';break;case 'r':r+='\r';break;case 't':r+='\t';break;case 'u':{if(i+4>s.size())throw std::runtime_error("Bad unicode escape");unsigned x=0;for(int k=0;k<4;k++){char h=take();x=x*16+(h>='0'&&h<='9'?h-'0':h>='a'&&h<='f'?h-'a'+10:h-'A'+10);}if(x<128)r+=(char)x;else if(x<2048){r+=(char)(0xc0|(x>>6));r+=(char)(0x80|(x&63));}else{r+=(char)(0xe0|(x>>12));r+=(char)(0x80|((x>>6)&63));r+=(char)(0x80|(x&63));}break;}default:throw std::runtime_error("Invalid escape");}}else r+=c;}throw std::runtime_error("Unclosed string");}
V val(){ws();char c=s.at(i);if(c=='{'){take();V::O o;ws();if(s[i]=='}'){take();return V{o};}while(true){ws();auto k=str();ws();if(take()!=':')throw std::runtime_error("Missing colon");o.emplace(k,val());ws();char d=take();if(d=='}')break;if(d!=',')throw std::runtime_error("Invalid object");}return V{o};}if(c=='['){take();V::A a;ws();if(s[i]==']'){take();return V{a};}while(true){a.push_back(val());ws();char d=take();if(d==']')break;if(d!=',')throw std::runtime_error("Invalid array");}return V{a};}if(c=='"')return V{str()};if(s.compare(i,4,"true")==0){i+=4;return V{true};}if(s.compare(i,5,"false")==0){i+=5;return V{false};}if(s.compare(i,4,"null")==0){i+=4;return V{nullptr};}size_t st=i;while(i<s.size()&&(std::isdigit((unsigned char)s[i])||s[i]=='-'||s[i]=='+'||s[i]=='.'||s[i]=='e'||s[i]=='E'))++i;return V{std::stod(s.substr(st,i-st))};}
public:explicit Parser(std::string x):s(std::move(x)){}V parse(){auto x=val();ws();if(i!=s.size())throw std::runtime_error("Trailing JSON");return x;}};
const V&get(const V&v,const char*k){return std::get<V::O>(v.v).at(k);}const V*opt(const V&v,const std::string&k){auto&o=std::get<V::O>(v.v);auto it=o.find(k);return it==o.end()||std::holds_alternative<std::nullptr_t>(it->second.v)?nullptr:&it->second;}
const std::string&text(const V&v){return std::get<std::string>(v.v);}double num(const V&v){return std::get<double>(v.v);}bool boolean(const V&v){return std::get<bool>(v.v);}const V::A&arr(const V&v){return std::get<V::A>(v.v);}
Point2 pt(const V&v){const auto&a=arr(v);return {Meters{num(a[0])},Meters{num(a[1])}};}
ModelId id(const V&v){return ModelId{text(v)};}
Wall makeWall(const V&v){return Wall{id(get(v,"id")),WallAxis{pt(get(v,"start")),pt(get(v,"end"))},Meters{num(get(v,"height"))},Meters{num(get(v,"thickness"))},opt(v,"levelId")?id(*opt(v,"levelId")):ModelId{}};}
Level makeLevel(const V&v){return Level{id(get(v,"id")),text(get(v,"name")),Meters{num(get(v,"elevation"))},Meters{num(get(v,"height"))}};}
Opening makeOpening(const V&v){auto k=text(get(v,"kind"));return Opening{id(get(v,"id")),id(get(v,"hostWallId")),k=="door"?OpeningKind::Door:k=="window"?OpeningKind::Window:OpeningKind::Generic,Meters{num(get(v,"offset"))},Meters{num(get(v,"width"))},Meters{num(get(v,"height"))},Meters{num(get(v,"sill"))}};}
CatalogInstance makeCatalog(const V&v){auto bounds=DimensionBounds{Meters{.001},Meters{1000}};return CatalogInstance{id(get(v,"id")),text(get(v,"assetId")),pt(get(v,"position")),num(get(v,"rotation")),id(get(v,"levelId")),id(get(v,"hostWallId")),Meters{num(get(v,"width"))},Meters{num(get(v,"depth"))},Meters{num(get(v,"height"))},ScalingMode::FreeStretch,bounds,bounds,bounds,opt(v,"category")?text(*opt(v,"category")):"fixture",opt(v,"scheduleTag")?text(*opt(v,"scheduleTag")):""};}
Project initial(const V&f){const V s=get(f,"initialState");const V p=get(s,"project");Project x;x.id=id(get(p,"id"));x.name=text(get(p,"name"));for(auto&v:arr(get(s,"levels")))x.levels.push_back(makeLevel(v));for(auto&v:arr(get(s,"walls")))x.walls.push_back(makeWall(v));for(auto&v:arr(get(s,"joins")))x.joins.push_back(WallJoin{id(get(v,"id")),id(get(v,"wallA")),boolean(get(v,"endA")),id(get(v,"wallB")),boolean(get(v,"endB")),pt(get(v,"point"))});for(auto&v:arr(get(s,"openings")))x.openings.push_back(makeOpening(v));for(auto&v:arr(get(s,"catalogInstances")))x.catalogInstances.push_back(makeCatalog(v));return x;}
Mutation command(const V&v){auto op=text(get(v,"op"));if(op=="moveWall"){auto d=pt(get(v,"delta"));return commands::moveWall(id(get(v,"id")),d);}if(op=="resizeWall")return commands::resizeWall(id(get(v,"id")),Meters{num(get(v,"length"))});if(op=="createWall")return commands::createWall(makeWall(get(v,"wall")));if(op=="createLevel")return commands::createLevel(makeLevel(get(v,"level")));if(op=="deleteWall")return commands::deleteWall(id(get(v,"id")));if(op=="deleteLevel")return commands::deleteLevel(id(get(v,"id")));if(op=="batch"){std::vector<Mutation>m;for(auto&c:arr(get(v,"commands")))m.push_back(command(c));return commands::batch(std::move(m));}throw std::runtime_error("Unsupported fixture command: "+op);}
void require(bool ok,const char*msg){if(!ok)throw std::runtime_error(msg);}
void writeSnapshot(const std::string&scenario,const Project&p,const fs::path&out){fs::create_directories(out);std::ofstream file(out/(scenario+".json"),std::ios::binary);file<<canonicalProjectJson(p);require(file.good(),"Failed writing parity snapshot");}
void runCrud(const V&f,const fs::path&out){Project seed=initial(f);if(!seed.id.valid())throw std::runtime_error("Initial project ID invalid: '"+seed.id.value+"'");CommandBus bus(std::move(seed));for(const auto&c:arr(get(f,"commands"))){const auto op=text(get(c,"op"));if(op=="undo"){require(bus.undo().ok(),"CRUD undo rejected");continue;}if(op=="redo"){require(bus.redo().ok(),"CRUD redo rejected");continue;}auto r=bus.execute(command(c));if(!r.ok())throw std::runtime_error("CRUD "+op+" rejected: "+r.error()->message);}
auto finalSnapshot=bus.snapshot();const Project&final=*finalSnapshot->project;require(final.walls.size()==1&&final.walls[0].id.value=="wall-1","CRUD final wall IDs mismatch");require(final.levels.size()==1&&final.levels[0].id.value=="level-1","CRUD final level IDs mismatch");require(std::abs(final.walls[0].axis.length().value-5.0)<1e-6,"CRUD resized wall length mismatch");
CommandBus rollback(initial(f));auto before=rollback.snapshot();auto bad=commands::batch({commands::createLevel(Level{ModelId{"level-1"},"Duplicate",Meters{0},Meters{3}}),commands::createWall(makeWall(arr(get(get(f,"initialState"),"walls")).front()))});auto rejected=rollback.execute(bad);require(!rejected.ok()&&rollback.snapshot()==before&&rollback.undoDepth()==0,"CRUD atomic rejection failed");
writeSnapshot("crud_batch",final,out);}
void runCascade(const V&f,const fs::path&out){CommandBus bus(initial(f));for(const auto&c:arr(get(f,"commands"))){const auto op=text(get(c,"op"));if(op=="deleteWall"){auto wid=id(get(c,"id"));auto r=bus.execute([wid](const Project&p){return deleteWallCascade(p,wid);});require(r.ok(),"cascade delete rejected");auto snapshot=bus.snapshot();const auto&s=*snapshot->project;require(s.walls.empty()&&s.openings.empty()&&s.catalogInstances.empty(),"cascade delete did not remove hosted entities");}else if(op=="undo"){require(bus.undo().ok(),"cascade undo failed");auto currentSnapshot=bus.snapshot();const auto&s=*currentSnapshot->project;require(s.walls.size()==1&&s.openings.size()==1&&s.catalogInstances.size()==1,"cascade undo failed to restore entities");}else if(op=="redo"){require(bus.redo().ok(),"cascade redo failed");auto snapNow=bus.snapshot();const auto&s=*snapNow->project;require(s.walls.empty()&&s.openings.empty()&&s.catalogInstances.empty(),"cascade redo failed");}else throw std::runtime_error("Unsupported cascade operation: "+op);}
auto lastSnapshot=bus.snapshot();writeSnapshot("cascade_delete",*lastSnapshot->project,out);}
}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("Usage: native_parity_runner <fixture-dir> <output-dir>");fs::path fixtures=argv[1],out=argv[2];std::ifstream a(fixtures/"crud_batch.json"),b(fixtures/"cascade_delete.json");require(a.good()&&b.good(),"Fixture paths not found");std::ostringstream sa,sb;sa<<a.rdbuf();sb<<b.rdbuf();runCrud(Parser(sa.str()).parse(),out);runCascade(Parser(sb.str()).parse(),out);return 0;}catch(const std::exception&e){std::fprintf(stderr,"native parity runner: %s\n",e.what());return 1;}}
